function facilitiesView(){const c=ccur(),f=c.facilities||(c.facilities={stadium:1,training:1,academy:1});return '<div class="hero-card"><div><span class="eyebrow">CLUB DEVELOPMENT</span><h2>🏟️ توسعه باشگاه</h2><p>ورزشگاه درآمد بازی‌های خانگی می‌سازد، مرکز تمرین پیشرفت بازیکنان را بهتر می‌کند و آکادمی استعداد جوان پیدا می‌کند.</p><span class="pill good">هواداران: '+num(c.fans||12000)+'</span></div><div class="hero-icon">🏗️</div></div><div class="grid stats-grid">'+stat("ورزشگاه",num(f.stadium)+"/۵","سطح فعلی")+stat("مرکز تمرین",num(f.training)+"/۵","افزایش بازده تمرین")+stat("آکادمی",num(f.academy)+"/۵","استعدادیابی")+stat("هواداران",num(c.fans||12000),"رشد با نتایج")+'</div><div class="grid two-col">'+[{k:"stadium",t:"🏟️ ورزشگاه",cost:8000000,d:"درآمد هر بازی خانگی افزایش می‌یابد."},{k:"training",t:"🏋️ مرکز تمرین",cost:7000000,d:"هر سطح، بازده تمرین را ۸٪ بهتر می‌کند."},{k:"academy",t:"🌱 آکادمی جوانان",cost:9000000,d:"سطح بالاتر استعداد بهتری پیدا می‌کند."}].map(x=>{const lv=f[x.k];return '<section class="panel"><h3>'+x.t+' · سطح '+num(lv)+'/۵</h3><p class="muted">'+x.d+'</p>'+(lv>=5?'<button class="btn ghost" disabled>حداکثر سطح</button>':'<button class="btn primary" data-action="upgrade-facility" data-facility="'+x.k+'">ارتقا · '+money(x.cost*lv)+'</button>')+'</section>'}).join("")+'</div><section class="panel" style="margin-top:14px"><h3>🌟 استعدادیابی جوانان</h3><p class="muted">هر فصل یک‌بار می‌توانی با هزینه ۱٫۵ تا ۴ میلیون، بازیکن ۱۶ تا ۱۹ ساله جذب کنی.</p>'+(c.academyScoutedSeason===state.season?'<span class="pill">این فصل انجام شده</span>':'<button class="btn green" data-action="scout-youth">پیدا کردن استعداد</button>')+'</section>'}
