function playCupRound(){const cup=state.cup;if(!cup||cup.champion){toast("جام به پایان رسیده است؛ می‌توانی جام جدید شروع کنی.");return}if(cup.matches.some(m=>!m.played)){cup.matches.forEach(m=>{const h=club(m.home),a=club(m.away);const power=c=>{const ps=c.players.filter(p=>p.starter);const list=ps.length?ps:c.players;return list.reduce((sum,p)=>sum+p.rating*(p.fitness||80)/100,0)/Math.max(1,list.length)};let hp=power(h)+Math.random()*18+(h.id===state.clubId?2:0),ap=power(a)+Math.random()*18+(a.id===state.clubId?2:0);let hg=clamp(Math.round(Math.random()*2+(hp-ap)/13),0,5),ag=clamp(Math.round(Math.random()*2+(ap-hp)/13),0,5);if(hg===ag){if(Math.random()>.5)hg++;else ag++}m.played=true;m.homeGoals=hg;m.awayGoals=ag;m.winner=hg>ag?h.id:a.id});cup.history.push({round:cup.round,matches:JSON.parse(JSON.stringify(cup.matches))})}if(cup.round===3){cup.champion=cup.matches[0].winner;log("قهرمان جام حذفی فصل "+num(state.season)+": "+club(cup.champion).name,"افتخارات");commit("قهرمان جام حذفی: "+club(cup.champion).name);return}const winners=cup.matches.map(m=>m.winner);cup.round++;cup.matches=Array.from({length:winners.length/2},(_,i)=>({id:"cup_"+cup.season+"_r"+cup.round+"_"+i,round:cup.round,home:winners[i*2],away:winners[i*2+1],played:false,homeGoals:null,awayGoals:null,winner:null}));commit("مرحله "+({2:"نیمه‌نهایی",3:"فینال"}[cup.round]||"بعدی")+" جام حذفی آماده شد.")}
