function getp(id){return ccur().players.find(p=>p.id===id)}
function release(id){let c=ccur(),p=getp(id);if(!p)return;if(c.players.length<=1){toast("حداقل یک بازیکن باید بماند.");return}c.players=c.players.filter(x=>x.id!==id);state.market=state.market.filter(x=>x.id!=="mkt_"+id);log(p.name+" آزاد شد؛ درآمد صفر","فهرست");commit("بازیکن آزاد شد؛ درآمد: ۰ ت")}
function sell(id){let c=ccur(),p=getp(id);if(!p)return;if(c.players.length<=1){toast("حداقل یک بازیکن باید بماند.");return}let fee=Math.round(p.value*.75);c.players=c.players.filter(x=>x.id!==id);state.market=state.market.filter(x=>x.id!=="mkt_"+id);c.budget+=fee;log(p.name+" فروخته شد؛ "+money(fee),"نقل‌وانتقالات");commit("فروش انجام شد؛ "+money(fee)+" به بودجه اضافه شد.")}
function buy(id){let c=ccur(),p=state.market.find(x=>x.id===id);if(!p)return;if(c.players.length>=c.capacity){toast("فهرست پر است؛ ابتدا بازیکن بفروش یا آزاد کن.");return}if(c.budget<p.asking){toast("بودجه برای این خرید کافی نیست.");return}let source=p.clubId?club(p.clubId):null,originalId=p.id.replace("mkt_","");if(source){if(source.players.length<=1){toast("باشگاه فروشنده نمی‌تواند بدون بازیکن بماند.");return}source.players=source.players.filter(x=>x.id!==originalId);source.budget+=p.asking}let np={...p,id:"signed_"+Date.now(),clubId:c.id,starter:c.players.length<11,injury:0};delete np.asking;c.players.push(np);c.budget-=p.asking;state.market=state.market.filter(x=>x.id!==id);log(np.name+" جذب شد؛ "+money(p.asking),"نقل‌وانتقالات");commit("خرید بازیکن انجام شد.")}
function refreshMarket(){state.market=marketSeed(state).map(p=>({...p,asking:Math.round(p.asking*(0.92+Math.random()*0.2))})).sort(()=>Math.random()-.5);log("فهرست نقل‌وانتقالات تازه‌سازی شد","بازار");commit("فهرست بازار تازه شد؛ قیمت‌ها ممکن است متفاوت باشند.")}
function train(){let c=ccur(),improved=0;c.players.forEach(p=>{if(state.training==="fitness"){p.fitness=clamp(p.fitness+14,0,100);p.injury=Math.max(0,p.injury-1);return}if(p.age>=35&&Math.random()<.65){p.fitness=clamp(p.fitness-8,20,100);return}p.fitness=clamp(p.fitness-6,20,100);let gain=p.age<=21?0.32:p.age<=27?0.22:p.age<=32?0.12:0.05;const targeted=(state.training==="goalkeeper"&&p.position==="دروازه‌بان")||(state.training==="defense"&&p.position==="مدافع")||(state.training==="midfield"&&p.position==="هافبک")||(state.training==="attack"&&p.position==="مهاجم");if(targeted)gain+=0.48;gain*=1+(((ccur().facilities||{}).training||1)-1)*0.08;if(state.training==="attack"&&(p.position==="مهاجم"||p.position==="هافبک"))p.shoot=clamp(p.shoot+1,0,99);if(state.training==="defense"&&(p.position==="مدافع"||p.position==="هافبک"))p.defense=clamp(p.defense+1,0,99);if(state.training==="midfield"&&p.position==="هافبک")p.pass=clamp(p.pass+1,0,99);if(state.training==="goalkeeper"&&p.position==="دروازه‌بان"){p.defense=clamp(p.defense+1,0,99);p.fitness=clamp(p.fitness-2,20,100)}if(Math.random()<gain){p.rating=clamp(p.rating+1,1,99);improved++}});log("جلسه تمرینی "+({balanced:"متعادل",fitness:"آمادگی جسمانی",attack:"هجومی",defense:"دفاعی",midfield:"هافبک‌ها",goalkeeper:"دروازه‌بان‌ها"}[state.training]||"تیمی")+" اجرا شد؛ "+improved+" بازیکن پیشرفت کرد","تمرین");commit("تمرین انجام شد؛ "+num(improved)+" بازیکن پیشرفت کرد.")}
function individual(id){let p=getp(id);if(!p)return;if(p.fitness<15){toast("آمادگی بازیکن کافی نیست.");return}p.rating=clamp(p.rating+1,1,99);p.fitness=clamp(p.fitness-8,0,100);p.morale=clamp(p.morale+2,0,100);log("تمرین فردی "+p.name,"تمرین");commit("قدرت بازیکن یک واحد افزایش یافت.")}
function predict(id){let m=state.fixtures.find(x=>x.id===id);if(!m||m.played){toast("این مسابقه قابل پیش‌بینی نیست.");return}if(state.predictions[id]){toast("قبلاً پیش‌بینی ثبت شده است.");return}let h=Number($("#ph-"+id).value),a=Number($("#pa-"+id).value);if(!Number.isInteger(h)||!Number.isInteger(a)||h<0||a<0||h>9||a>9){toast("گل‌ها باید عدد صحیح بین صفر تا ۹ باشند.");return}state.predictions[id]={home:h,away:a};log("پیش‌بینی رایگان ثبت شد: "+h+" - "+a,"پیش‌بینی");commit("پیش‌بینی رایگان ثبت شد.")}
function filterPlayers(){let q=$("#ps")?.value||"",pos=$("#pp")?.value||"",sort=$("#psort")?.value||"rating",a=ccur().players.filter(p=>p.name.includes(q)&&(!pos||p.position===pos));a.sort((x,y)=>sort==="age"?x.age-y.age:sort==="value"?y.value-x.value:sort==="fitness"?y.fitness-x.fitness:y.rating-x.rating);$("#player-grid").innerHTML=a.length?a.map(p=>card(p)).join(""):'<div class="empty">بازیکنی پیدا نشد.</div>'}
